dtsPropsFor.Icon:
/** One of the bundled Lucide icon names. */
  name: "stage" | "apps" | "input" | "display" | "settings" | "refresh" | "check" | "alert-triangle" | "alert-circle" | "info" | "arrow-right" | "chevron-down" | "chevron-right" | "file-up" | "download" | "external-link" | "folder-open" | "camera" | "volume" | "power" | "play" | "pause" | "search" | "plus" | "minus" | "x" | "copy" | "mouse" | "pencil" | "trash" | "eye" | "eye-off" | "undo" | "save" | "app-window" | "hard-drive" | "smartphone";
  /** Pixel size of the square icon. 20 in navigation and toolbars, 18 in buttons, 16 inline. */
  size?: number;
  /** 1.5 next to regular text, 2 next to semibold text (DESIGN.md 6). */
  strokeWidth?: number;
  className?: string;

dtsPropsFor.Button:
children: React.ReactNode;
  /** `primary` is the one main action of a view. `danger` is a quiet red text button (row actions such as 제거); `danger-solid` confirms something that cannot be undone inside a dialog. */
  variant?: "primary" | "secondary" | "ghost" | "danger" | "danger-solid";
  /** `large` is the 44px wizard main button; the default is 40px. */
  size?: "default" | "large";
  /** Leading 18px icon. */
  icon?: "stage" | "apps" | "input" | "display" | "settings" | "refresh" | "check" | "alert-triangle" | "alert-circle" | "info" | "arrow-right" | "chevron-down" | "chevron-right" | "file-up" | "download" | "external-link" | "folder-open" | "camera" | "volume" | "power" | "play" | "pause" | "search" | "plus" | "minus" | "x" | "copy" | "mouse" | "pencil" | "trash" | "eye" | "eye-off" | "undo" | "save" | "app-window" | "hard-drive" | "smartphone";
  onClick?: () => void | Promise<void>;
  disabled?: boolean;
  type?: "button" | "submit";
  className?: string;
  autoFocus?: boolean;

dtsPropsFor.Chip:
children: React.ReactNode;
  /** Status colors only for real states (DESIGN.md 2); `muted` for everything else. */
  tone?: "muted" | "accent" | "success" | "warning" | "danger";
  /** Leading 14px icon. */
  icon?: "stage" | "apps" | "input" | "display" | "settings" | "refresh" | "check" | "alert-triangle" | "alert-circle" | "info" | "arrow-right" | "chevron-down" | "chevron-right" | "file-up" | "download" | "external-link" | "folder-open" | "camera" | "volume" | "power" | "play" | "pause" | "search" | "plus" | "minus" | "x" | "copy" | "mouse" | "pencil" | "trash" | "eye" | "eye-off" | "undo" | "save" | "app-window" | "hard-drive" | "smartphone";

dtsPropsFor.EmptyState:
title: string;
  /** 32px icon above the title. */
  icon?: "stage" | "apps" | "input" | "display" | "settings" | "refresh" | "check" | "alert-triangle" | "alert-circle" | "info" | "arrow-right" | "chevron-down" | "chevron-right" | "file-up" | "download" | "external-link" | "folder-open" | "camera" | "volume" | "power" | "play" | "pause" | "search" | "plus" | "minus" | "x" | "copy" | "mouse" | "pencil" | "trash" | "eye" | "eye-off" | "undo" | "save" | "app-window" | "hard-drive" | "smartphone";
