dtsPropsFor.Field:
label: string;
  /** Hide the label visually and keep it as the accessible name (search boxes). */
  labelHidden?: boolean;
  value: string;
  onChange: (value: string) => void;
  type?: "text" | "number" | "search";
  placeholder?: string;
  /** Leading 18px icon inside the box. */
  icon?: "stage" | "apps" | "input" | "display" | "settings" | "refresh" | "check" | "alert-triangle" | "alert-circle" | "info" | "arrow-right" | "chevron-down" | "chevron-right" | "file-up" | "download" | "external-link" | "folder-open" | "camera" | "volume" | "power" | "play" | "pause" | "search" | "plus" | "minus" | "x" | "copy" | "mouse" | "pencil" | "trash" | "eye" | "eye-off" | "undo" | "save" | "app-window" | "hard-drive" | "smartphone";
  /** Unit after the input, for example `px` or `DPI`. */
  suffix?: string;
  min?: number;
  max?: number;
  step?: number;
  /** One short sentence under the input, for example the allowed range. */
  hint?: string;
  invalid?: boolean;
  disabled?: boolean;
  onEnter?: () => void;

dtsPropsFor.IconButton:
icon: "stage" | "apps" | "input" | "display" | "settings" | "refresh" | "check" | "alert-triangle" | "alert-circle" | "info" | "arrow-right" | "chevron-down" | "chevron-right" | "file-up" | "download" | "external-link" | "folder-open" | "camera" | "volume" | "power" | "play" | "pause" | "search" | "plus" | "minus" | "x" | "copy" | "mouse" | "pencil" | "trash" | "eye" | "eye-off" | "undo" | "save" | "app-window" | "hard-drive" | "smartphone";
  /** Accessible name and tooltip. Icon-only buttons always carry one. */
  label: string;
  onClick?: () => void | Promise<void>;
  /** When set, the button is a toggle and exposes `aria-pressed`. */
  pressed?: boolean;
  disabled?: boolean;
