dtsPropsFor.Segmented:
/** Accessible name of the group. */
  label: string;
  options: readonly { value: string; label: string; disabled?: boolean }[];
  /** Selected value, or null when none is selected yet. */
  value: string | null;
  onChange: (value: string) => void | Promise<void>;
  disabled?: boolean;

dtsPropsFor.Select:
/** Accessible name; usually the setting row label. */
  label: string;
  options: readonly { value: string; label: string }[];
  value: string;
  onChange: (value: string) => void | Promise<void>;
  disabled?: boolean;

dtsPropsFor.StepList:
/** Each item: noun-phrase label; the symbol says done, in progress, pending or failed. `children` is an optional detail line (vertical lists only). */
  items: readonly { id: string; label: string; state: "done" | "active" | "pending" | "failed"; children?: React.ReactNode }[];
  /** Accessible name of the list. */
  label: string;
  /** `horizontal` joins the steps with arrows (download: 다운로드 중 → 무결성 확인 → 완료). */
  orientation?: "vertical" | "horizontal";

dtsPropsFor.Rail:
current: "stage" | "apps" | "input" | "display" | "settings";
  onSelect: (item: "stage" | "apps" | "input" | "display" | "settings") => void;
  /** Drives the status dot at the bottom. */
  guestState: "stopped" | "starting" | "running" | "stopping" | "restarting" | "failed";
  /** Product version shown under the dot. */
  version: string;
